(() => {
const reduce=matchMedia('(prefers-reduced-motion: reduce)'),fine=matchMedia('(pointer: fine)');
const model=document.querySelector('#mclaren'),home=document.querySelector('#home');
let scrollFrame=0,flight=0;
function updateScroll(){scrollFrame=0;if(!home||!model)return;const progress=Math.max(0,Math.min(1,scrollY/Math.max(1,model.offsetTop)));document.documentElement.style.setProperty('--journey',reduce.matches?1:progress);home.style.setProperty('--depart',reduce.matches?0:progress)}
window.addEventListener('scroll',()=>{if(!scrollFrame)scrollFrame=requestAnimationFrame(updateScroll)},{passive:true});window.addEventListener('resize',updateScroll);updateScroll();
function stopFlight(){cancelAnimationFrame(flight);flight=0;document.documentElement.classList.remove('cinematic-scroll')}
for(const type of ['wheel','touchstart','pointerdown','keydown'])window.addEventListener(type,stopFlight,{passive:true});
document.querySelector('.landing-scroll')?.addEventListener('click',e=>{if(!model)return;e.preventDefault();stopFlight();if(reduce.matches){model.scrollIntoView({behavior:'instant'});return}const start=scrollY,end=model.getBoundingClientRect().top+scrollY,t0=performance.now();document.documentElement.classList.add('cinematic-scroll');function travel(now){const t=Math.min(1,(now-t0)/2600),ease=t*t*t*(t*(t*6-15)+10);window.scrollTo({top:start+(end-start)*ease,behavior:'instant'});if(t<1)flight=requestAnimationFrame(travel);else{stopFlight();history.replaceState(null,'','#mclaren');document.querySelector('#carViewport')?.focus({preventScroll:true})}}flight=requestAnimationFrame(travel)});
// Slow physical wheel scrolling without blocking touch, zoom or nested scroll areas.
let wheelFrame=0,wheelTarget=scrollY,wheelLast=0;
function cancelWheel(){cancelAnimationFrame(wheelFrame);wheelFrame=0;wheelTarget=scrollY}
function easeWheel(now){wheelFrame=0;const dt=Math.min(40,now-wheelLast)||16;wheelLast=now;const gap=wheelTarget-scrollY;if(Math.abs(gap)<.3){window.scrollTo({top:wheelTarget,behavior:'instant'});return}window.scrollTo({top:scrollY+gap*(1-Math.exp(-dt/155)),behavior:'instant'});wheelFrame=requestAnimationFrame(easeWheel)}
function nestedScroll(target){for(let el=target;el&&el!==document.body;el=el.parentElement){if(el.matches?.('dialog,input,textarea,select,[contenteditable="true"]'))return true;const css=getComputedStyle(el);if(/auto|scroll/.test(css.overflowY)&&el.scrollHeight>el.clientHeight+2)return true}return false}
window.addEventListener('wheel',e=>{if(!fine.matches||e.ctrlKey||e.metaKey||e.shiftKey||Math.abs(e.deltaX)>Math.abs(e.deltaY)||nestedScroll(e.target))return;e.preventDefault();stopFlight();const unit=e.deltaMode===1?16:e.deltaMode===2?innerHeight:1,delta=e.deltaY*unit*.18,limit=document.documentElement.scrollHeight-innerHeight;if(!wheelFrame)wheelTarget=scrollY;wheelTarget=Math.max(0,Math.min(limit,Math.max(scrollY-innerHeight*.45,Math.min(scrollY+innerHeight*.45,wheelTarget+delta))));if(reduce.matches){window.scrollTo({top:wheelTarget,behavior:'instant'});return}if(!wheelFrame){wheelLast=performance.now();wheelFrame=requestAnimationFrame(easeWheel)}},{passive:false});
for(const event of ['touchstart','pointerdown','keydown'])window.addEventListener(event,cancelWheel,{passive:true});window.addEventListener('resize',cancelWheel);document.addEventListener('visibilitychange',()=>{if(document.hidden)cancelWheel()});
if(!fine.matches||reduce.matches)return;
const aura=document.createElement('div');aura.className='cursor-aura';aura.setAttribute('aria-hidden','true');aura.innerHTML='<i></i><i></i><i></i><b><span></span></b>';document.body.append(aura);
const blobs=[...aura.querySelectorAll('i')],ring=aura.querySelector('b'),label=ring.querySelector('span'),points=Array.from({length:3},()=>({x:0,y:0}));
let tx=0,ty=0,raf=0,until=0,last=0,initialized=false;
function draw(now){raf=0;const dt=Math.min((now-last)/1000,.04)||.016;last=now;let moved=0;points.forEach((p,i)=>{const target=i?points[i-1]:{x:tx,y:ty},ease=1-Math.exp(-dt*(i?12:25));p.x+=(target.x-p.x)*ease;p.y+=(target.y-p.y)*ease;blobs[i].style.transform=`translate3d(${p.x}px,${p.y}px,0)`;moved+=Math.abs(target.x-p.x)+Math.abs(target.y-p.y)});ring.style.transform=`translate3d(${points[0].x}px,${points[0].y}px,0)`;if(now<until||moved>.3)raf=requestAnimationFrame(draw);else aura.classList.add('resting')}
window.addEventListener('pointermove',e=>{if(e.pointerType!=='mouse'||reduce.matches)return;tx=e.clientX;ty=e.clientY;if(!initialized){points.forEach(p=>{p.x=tx;p.y=ty});initialized=true}const overCar=!!e.target.closest('#carViewport'),interactive=!!e.target.closest('a,button,input');aura.classList.toggle('on-car',overCar);aura.classList.toggle('on-link',interactive);aura.classList.remove('resting','hidden');label.textContent=overCar?(e.buttons?'ROTATE':'REVEAL'):'';until=performance.now()+180;if(!raf){last=performance.now();raf=requestAnimationFrame(draw)}},{passive:true});
document.addEventListener('pointerleave',()=>aura.classList.add('hidden'));document.addEventListener('visibilitychange',()=>{if(document.hidden){cancelAnimationFrame(raf);raf=0;aura.classList.add('hidden')}});reduce.addEventListener('change',()=>{aura.hidden=reduce.matches;cancelAnimationFrame(raf);raf=0});
})();
